from taf.config.testline import Airphone, Simulator


class TestlineConfigurationInformationProvider:
    def __init__(self, tl_config, **kwargs):
        super(TestlineConfigurationInformationProvider, self).__init__(**kwargs)
        self._tl_config = tl_config

    def get_all_network_elements(self):
        gnbs = [f'gnb_{i}' for i in range(len(self._tl_config.gnbs))] if self._tl_config.gnbs else []
        enbs = [f'enb_{i}' for i in range(len(self._tl_config.enbs))] if self._tl_config.enbs else []
        ues = [f'ue_{i}' for i in range(len(self._tl_config.ues))] if self._tl_config.ues else []
        # Todo: need to add the other network elements like UEs, etc.
        return enbs + gnbs + ues

    def get_lmp_connection(self, node_id=0, node_type='gnb', du_id=0, comu_id=0):
        """
        Provide the lmp connection go the given network element

        :param int node_id: The index of the network element in the corresponding list of testline config.
        :param str node_type: The node type, 'gnb', 'enb' or 'ue'.
        :param int du_id: The index of the DU in the given node.
        :param int comu_id: The index of the common unit in the given DU.
        """
        if node_type == 'gnb':
            return self._tl_config.gnbs[node_id].dus[du_id].airscale.common_units[comu_id].lmp_connection
        elif node_type == 'enb':
            return self._tl_config.enbs[node_id].system_module.common_units[comu_id].lmp_connection

    def get_deployment_type(self, node_id):
        """
        Provides the deployment type for the given node_id.

        :param int node_id: The node_id to determine the gNodeB in the testline configuration.
        :returns: 'cloud' or 'classical'
        """
        if hasattr(self._tl_config.gnbs[node_id], 'cloud_deployment') and \
                self._tl_config.gnbs[node_id].cloud_deployment is not None:
            return 'cloud'
        else:
            return 'classical'

    def get_ue_type(self, node_id):
        """Provide the type of UE.

        :param int node_id: The index of the UE/network element in UE list of testline config.
        """
        ue = self._tl_config.ues[node_id]
        if isinstance(ue, Airphone) or isinstance(ue, Simulator):
            return 'airphone'
        return 'unknown'

    def get_oam_http_connection(self, node_id=0):
        """
        Provide the OAM HTTP connection.

        :param int node_id: The index of the network element in the corresponding list of testline config.
        """
        return self._tl_config.gnbs[node_id].cu.oam_http_connection_details

    def get_web_service(self, node_id):
        oam_http_connection = self.get_oam_http_connection(node_id=node_id)
        web_service = {
            'host': oam_http_connection.addr,
            'user': oam_http_connection.username,
            'password': oam_http_connection.password,
            'port': 443
        }
        return web_service

    def get_backhaul_site_oam_ip(self, node_id=0):
        """
        Provide the backhaul site OAM IP address.

        :param int node_id: The index of the network element in the corresponding list of testline config.
        """
        return self._tl_config.gnbs[node_id].cu.backhaul_site_oam_ip

    def _get_test_pc_for_nodeb(self, nodeb):
        """
        Determines the test pc by the given nodeb inside of the given testline configuration.
        It is checked in the list of given test pcs, which test pc has a entry in its list of connections
        to the given nodeb. The corresponding test pc is returned. If no test pc was found, the first
        element of the test_pcs list in the testine configuration is returned.

        :param nodeb: The nodeb configuration object in the testline config.
        """
        if self._tl_config.test_pcs is None:
            return self._tl_config.test_pc

        test_pcs = [test_pc for test_pc in self._tl_config.test_pcs for obj in test_pc.connections if obj is nodeb]
        if test_pcs:
            return test_pcs[0]

        return self._tl_config.test_pc

    def get_test_pc(self, node_id=0, node_type='gnb'):
        """
        Provides the test pc which is directly connected to the given network element.

        :param int node_id: The index of the network element in the corresponding list of testline config.
        :param str node_type: The node type, 'gnb' or 'enb'.
        """

        if node_type == 'gnb':
            return self._get_test_pc_for_nodeb(self._tl_config.gnbs[node_id])
        elif node_type == 'enb':
            return self._get_test_pc_for_nodeb(self._tl_config.enbs[node_id])

        raise AssertionError(f"Error in getting node: invalid node type {node_type}")

    def get_cu_master_node_ssh_details(self, node_id=0):
        """
        Provide the CU master node SSH details from the testline configuration.

        :param int node_id: The index of the network element in the corresponding list of testline config.
        """
        return self._tl_config.gnbs[node_id].cloud_deployment.cloud_hosting.master_node.ssh_connection_details

    def get_vdu_master_node_ssh_details(self, node_id=0, vdu_id=0):
        """
        Provide the vDU master node SSH details from the testline configuration

        :param int node_id: The index of the network element in the corresponding list of testline config.
        :param int vdu_id: The index of the vdu in the gNodeB configuration.
        """
        return self._tl_config.gnbs[node_id].dus[vdu_id].cloud_deployment.cloud_hosting.master_node.ssh_connection_details

    def get_vdu_namespace(self, node_id, vdu_id):
        """
        Provide the vDU namespace for the given network element.

        :param int node_id: The index of the network element in the corresponding list of testline config.
        :param int du_id: The du_id. If set to 'None', the cu is used to retrieve pod names.
        """
        return self._tl_config.gnbs[node_id].dus[vdu_id].cloud_deployment.cloud_hosting.namespace

    def get_cu_namespace(self, node_id):
        """
        Provide the CU namespace for the given network element.

        :param int node_id: The index of the network element in the corresponding list of testline config.
        """
        return self._tl_config.gnbs[node_id].cloud_deployment.cloud_hosting.namespace

    def get_du_ids(self, node_id):
        return range(len(self._tl_config.gnbs[node_id].dus))

    def get_k8s_cu_proxy(self, node_id):
        """
        Get network proxy to access CU nodes.
        """
        cu_master_node = self._tl_config.gnbs[node_id].cloud_deployment.cloud_hosting.master_node
        return {'host': cu_master_node.k8s_connection_details.ip_addr,
                'user': cu_master_node.k8s_connection_details.username,
                'password': cu_master_node.k8s_connection_details.password}

    def get_k8s_vdu_proxy(self, node_id, vdu_id):
        """
        Get network proxy to access VDU nodes.
        """
        vdu_master_node = self._tl_config.gnbs[node_id].dus[vdu_id].cloud_deployment.cloud_hosting.master_node
        return {'host': vdu_master_node.k8s_connection_details.ip_addr,
                'user': vdu_master_node.k8s_connection_details.username,
                'password': vdu_master_node.k8s_connection_details.password}

    def get_vdu_oam_http_connection_details(self, node_id=0, vdu_id=0):
        """
        Provide the vDU OAM HTTP details from the testline configuration.

        :param int node_id: The index of the network element in the corresponding list of testline config.
        :param int vdu_id: The index of the vDU in the gNodeB configuration.
        """
        vdu_http_connection = self._tl_config.gnbs[node_id].dus[vdu_id].oam_http_connection_details
        return {'host': vdu_http_connection.addr,
                'user': vdu_http_connection.username,
                'password': vdu_http_connection.password,
                'port': vdu_http_connection.port}

    def get_cu_oam_http_connection_details(self, node_id=0):
        """
        Provide the CU master OAM HTTP details from the testline configuration.

        :param int node_id: The index of the network element in the corresponding list of testline config.
        """
        cu_http_connection = self._tl_config.gnbs[node_id].cu.oam_http_connection_details
        return {'host': cu_http_connection.addr,
                'user': cu_http_connection.username,
                'password': cu_http_connection.password,
                'port': cu_http_connection.port}

    def is_aic(self, node_id=0):
        return hasattr(self._tl_config.gnbs[node_id], 'cloud_deployment') and \
            self._tl_config.gnbs[node_id].cloud_deployment is not None

    def get_ue_lmp_connection(self, node_id=0):
        return self._tl_config.ues[node_id].l1.common_units[0].lmp_connection
